use std::env
use std::fs
use std::process

fn pad6(n: int) -> string {
    let s = "${n}"
    let mut out = ""
    let mut i = s.len()
    while i < 6 {
        out = out + " "
        i += 1
    }
    out + s
}

fn main() {
    let args = env::args()
    let mut number = false
    let mut files: Vec<string> = Vec::new()
    for a in args {
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut failed = false
    let mut counter = 0
    let mut out = ""
    if files.len() == 0 {
        files.push("/dev/stdin")
    }
    for f in files {
        match fs::read_to_string(f) {
            Ok(text) => {
                if number {
                    let mut parts: Vec<string> = text.split("\n").collect()
                    if parts.len() > 0 && parts[parts.len() - 1] == "" {
                        parts.pop()
                    }
                    for line in parts {
                        counter += 1
                        out = out + pad6(counter) + "\t" + line + "\n"
                    }
                } else {
                    out = out + text
                }
            },
            Err(_) => {
                failed = true
                out = out + "cat: ${f}: No such file\n"
            }
        }
    }
    print("${out}")
    if failed {
        process::exit(1)
    }
}

